#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
umask 077
ENV_FILE="$PWD/.newsletter-ca-wizard.env"
chart_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")/../helm/newsletter" && pwd)

die() { warn "$1"; exit 1; }
k() { kubectl "--context=$CA_CONTEXT" "--namespace=$CA_NAMESPACE" "$@"; }
h() { helm "--kube-context=$CA_CONTEXT" "--namespace=$CA_NAMESPACE" "$@"; }
ask_default() {
  local key="$1" prompt="$2" fallback="$3"
  ask "$key" "$prompt [$fallback]:"
  [[ -n "${!key}" ]] || printf -v "$key" '%s' "$fallback"
  [[ -n "${!key}" ]] || die "A value is required."
  write_env "$key" "${!key}"
}

# Public certificate files and private temporary snapshots are never printed
# wholesale. Certificate subject, issuer and fingerprints are public.
ca_helper() {
  python3 - "$@" <<'PY'
import datetime
import hashlib
import json
import pathlib
import re
import subprocess
import sys
from urllib.parse import urlsplit, urlunsplit
import yaml

def openssl(args, data):
    result = subprocess.run(["openssl", "x509", *args], input=data, capture_output=True)
    if result.returncode:
        raise ValueError("Cannot read this certificate. Supply a PEM or DER X.509 CA certificate.")
    return result.stdout

def main():
    mode = sys.argv[1]
    if mode == "cert":
        source, target = map(pathlib.Path, sys.argv[2:4])
        data = source.read_bytes()
        if b"PRIVATE KEY" in data:
            raise ValueError("The file contains a private key. Supply public CA certificates only.")
        blocks = re.findall(rb"-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----", data, re.S)
        if b"-----BEGIN" in data:
            if not blocks or data.count(b"-----BEGIN CERTIFICATE-----") != len(blocks):
                raise ValueError("The PEM certificate is missing or incomplete.")
        else:
            blocks = [openssl(["-inform", "DER", "-outform", "PEM"], data)]
        existing = target.read_bytes() if target.exists() else b""
        additions, summaries = [], []
        for block in blocks:
            normalized = openssl(["-outform", "PEM"], block)
            details = openssl(["-noout", "-ext", "basicConstraints"], normalized).decode()
            if "CA:TRUE" not in details:
                raise ValueError("This is not a CA certificate. Supply the issuing root/intermediate CA.")
            now = datetime.datetime.now(datetime.timezone.utc)
            for line in openssl(["-noout", "-startdate", "-enddate"], normalized).decode().splitlines():
                key, value = line.split("=", 1)
                date = datetime.datetime.strptime(value, "%b %d %H:%M:%S %Y %Z").replace(tzinfo=datetime.timezone.utc)
                if (key == "notBefore" and date > now) or (key == "notAfter" and date <= now):
                    raise ValueError("A CA certificate is expired or not yet valid.")
            if normalized in existing or normalized in additions:
                summaries.append("Duplicate CA certificate: already included.")
                continue
            additions.append(normalized)
            summaries.append(openssl(["-noout", "-subject", "-issuer", "-fingerprint", "-sha256"], normalized).decode().strip())
        # Validate every certificate first; a bad bundle adds nothing.
        with target.open("ab") as handle:
            for block in additions:
                handle.write(block)
        print("\n".join(summaries))
    elif mode == "metadata":
        deployment = json.loads(pathlib.Path(sys.argv[2]).read_text())
        metadata = deployment["metadata"]
        labels, annotations = metadata.get("labels", {}), metadata.get("annotations", {})
        fields = {
            "release": annotations.get("meta.helm.sh/release-name") or labels.get("app.kubernetes.io/instance") or metadata["name"],
            "manager": "argocd" if annotations.get("argocd.argoproj.io/tracking-id") or labels.get("argocd.argoproj.io/instance") else "helm",
        }
        print(fields[sys.argv[3]])
    elif mode == "url":
        url = urlsplit(sys.argv[2])
        if url.scheme != "https" or not url.hostname or url.username or url.password or url.query or url.fragment:
            raise ValueError("Use an HTTPS repository URL without credentials, query parameters or a fragment.")
        _ = url.port
        path = url.path.rstrip("/").replace("/artifactory/api/storage/", "/artifactory/", 1)
        match = re.fullmatch(r"(.*?/artifactory)/([^/]+)(/.*)?", path)
        if not match:
            raise ValueError("Include the repository: https://host/artifactory/generic-local/newsletters.")
        print(urlunsplit(("https", url.netloc, match[1] + "/api/storage/" + match[2] + (match[3] or ""), "list&deep=1&listFolders=0", "")))
    elif mode == "values":
        source, bundle, target = map(pathlib.Path, sys.argv[2:5])
        text = source.read_text()
        before = yaml.safe_load(text)
        if not isinstance(before, dict):
            raise ValueError("The values file must be a YAML mapping.")
        if any(entry.get("name") == "NODE_EXTRA_CA_CERTS" for entry in before.get("extraEnv", []) or []):
            raise ValueError("Remove NODE_EXTRA_CA_CERTS from extraEnv first; the new chart sets it automatically.")
        # Preserve all other text/comments. Replace only this chart's CA section.
        lines = text.splitlines(keepends=True)
        starts = [i for i, line in enumerate(lines) if re.match(r"""^(?:artifactoryCa|"artifactoryCa"|'artifactoryCa')\s*:""", line)]
        if len(starts) > 1:
            raise ValueError("The values file has duplicate artifactoryCa sections.")
        pem = bundle.read_text()
        section = "artifactoryCa:\n  bundle: |\n" + "".join("    " + line + "\n" for line in pem.splitlines())
        if starts:
            start = starts[0]
            end = start + 1
            while end < len(lines) and (not lines[end].strip() or lines[end][0].isspace() or lines[end].startswith("#")):
                end += 1
            candidate = "".join(lines[:start]) + section + "\n" + "".join(lines[end:])
        else:
            candidate = text.rstrip() + "\n\n" + section
        expected = dict(before)
        expected["artifactoryCa"] = {"bundle": pem}
        if yaml.safe_load(candidate) != expected:
            raise ValueError("This YAML layout cannot be updated safely. Use a normal block-style YAML values file.")
        target.write_text(candidate)
        print("CA bundle prepared; all other values are preserved.")
    elif mode == "verify-plan":
        live = json.loads(pathlib.Path(sys.argv[2]).read_text())
        resources = list(yaml.safe_load_all(pathlib.Path(sys.argv[3]).read_text()))
        deployments = [r for r in resources if isinstance(r, dict) and r.get("kind") == "Deployment" and r["metadata"]["name"] == live["metadata"]["name"]]
        if len(deployments) != 1:
            raise ValueError("The rendered chart does not match the selected Deployment. Check the release and values files.")
        planned = deployments[0]
        old, new = live["spec"]["template"]["spec"], planned["spec"]["template"]["spec"]
        old_container = next(c for c in old["containers"] if c["name"] == "newsletter")
        new_container = next(c for c in new["containers"] if c["name"] == "newsletter")
        if old_container["image"] != new_container["image"]:
            raise ValueError("The planned image differs from the running image. Set the same image registry/repository/tag in your deployment values first.")
        if live["spec"]["selector"] != planned["spec"]["selector"]:
            raise ValueError("The planned workload selector differs from the running Deployment.")
        old_data = next(v for v in old["volumes"] if v["name"] == "pb-data")
        new_data = next(v for v in new["volumes"] if v["name"] == "pb-data")
        if old_data != new_data:
            raise ValueError("The planned data volume differs from the running Deployment. Check the persistence values.")
        old_mount = next(m for m in old_container["volumeMounts"] if m["name"] == "pb-data")
        new_mount = next(m for m in new_container["volumeMounts"] if m["name"] == "pb-data")
        if old_mount != new_mount:
            raise ValueError("The planned data mount differs from the running Deployment.")
        trust_env = next(e for e in new_container["env"] if e["name"] == "NODE_EXTRA_CA_CERTS")
        if trust_env["value"] != "/etc/newsletter-artifactory-ca/ca-bundle.pem":
            raise ValueError("The chart did not configure the CA file.")
        print("Planned image matches the running image: " + new_container["image"])
        print("Deployment selector and existing data volume/mount match.")
        print("The chart adds the CA ConfigMap, pod mount, environment and certificate checksum.")
        print("Review the full rendered plan locally before applying; it may contain existing secret values.")
    elif mode == "verify-installed":
        deployment = json.loads(pathlib.Path(sys.argv[2]).read_text())
        bundle = pathlib.Path(sys.argv[3]).read_text().strip()
        pod = deployment["spec"]["template"]
        container = next(c for c in pod["spec"]["containers"] if c["name"] == "newsletter")
        env = [e for e in container.get("env", []) if e["name"] == "NODE_EXTRA_CA_CERTS"]
        if env != [{"name": "NODE_EXTRA_CA_CERTS", "value": "/etc/newsletter-artifactory-ca/ca-bundle.pem"}]:
            raise ValueError("The running Deployment does not have the chart's CA environment setting. Check the deployed chart revision and values file.")
        if pod["metadata"].get("annotations", {}).get("checksum/artifactory-ca") != hashlib.sha256(bundle.encode()).hexdigest():
            raise ValueError("The running Deployment does not reference the selected CA bundle. Finish the Helm/ArgoCD deployment first.")
        print("The running Deployment references the selected persistent CA configuration.")
    else:
        raise ValueError("Unknown helper action.")

try:
    main()
except (ValueError, OSError, KeyError, StopIteration, yaml.YAMLError):
    # YAML parsing errors can echo source lines containing existing credentials.
    error = sys.exc_info()[1]
    message = str(error) if isinstance(error, ValueError) else "Cannot process the selected file/workload. Check its format and required fields."
    print("CA setup: " + message, file=sys.stderr)
    sys.exit(1)
PY
}

banner "Newsletter: persistent Artifactory CA setup"

stage "Select the cluster and deployment"
for tool in kubectl helm openssl python3; do
  command -v "$tool" >/dev/null 2>&1 || die "Install $tool on this machine, then re-run."
done
python3 -c 'import yaml' 2>/dev/null ||
  die "Install Python PyYAML (for example your Linux distribution's python3-yaml package), then re-run."
say "Use Bash on a workstation with access to the affected cluster."
say "Public selections are remembered in $ENV_FILE."
kubectl config get-contexts
default_context=$(kubectl config current-context 2>/dev/null || true)
ask_default CA_CONTEXT "Kubernetes context" "$default_context"
[[ -n "$(kubectl config get-contexts "$CA_CONTEXT" -o name)" ]] || die "That context does not exist."
kubectl "--context=$CA_CONTEXT" get namespaces -o name ||
  note "Namespace listing is unavailable; enter your known namespace."
ask_default CA_NAMESPACE "Existing Newsletter namespace" newsletter
k get deployments -o name || note "Deployment listing is unavailable; enter its known name."
ask_default CA_DEPLOYMENT "Newsletter Deployment name" newsletter
work_dir=$(mktemp -d)
trap 'rm -rf -- "$work_dir"' EXIT
k get deployment "$CA_DEPLOYMENT" -o json > "$work_dir/live.json"
default_release=$(ca_helper metadata "$work_dir/live.json" release)
default_manager=$(ca_helper metadata "$work_dir/live.json" manager)
ask_default CA_MANAGER "Deployment management: helm or argocd" "$default_manager"
[[ "$CA_MANAGER" == helm || "$CA_MANAGER" == argocd ]] || die "Choose helm or argocd."
ask_default CA_RELEASE "Helm release name (ArgoCD helm.releaseName when set)" "$default_release"
if [[ "$CA_MANAGER" == helm ]]; then
  h status "$CA_RELEASE" > "$work_dir/helm-status.txt"
  h get values "$CA_RELEASE" -o yaml > "$work_dir/release-values.yaml"
fi

stage "Choose the persistent deployment values file"
say "Chart: $chart_dir"
say "Choose the existing YAML values file used for this cluster's deployments."
say "For ArgoCD, select the file listed in the Application's helm.valueFiles."
say "For Helm, select the file you also use on future version upgrades."
while true; do
  ask CA_VALUES "Path to that deployment values file:"
  if [[ -f "$CA_VALUES" ]]; then break; fi
  warn "File not found. Enter an existing YAML values file."
done
CA_VALUES=$(python3 -c 'import pathlib,sys; print(pathlib.Path(sys.argv[1]).resolve())' "$CA_VALUES")
write_env CA_VALUES "$CA_VALUES"
say "If deployment uses other values files, add each one in order; this CA file is applied last."
additional_values=()
while confirm "Add another values file used by this deployment?"; do
  ask CA_OTHER_VALUES "Path to the additional values file:"
  [[ -f "$CA_OTHER_VALUES" ]] || die "That file does not exist."
  additional_values+=(-f "$CA_OTHER_VALUES")
done
pause "Press Enter to choose your certificates."

stage "Validate and combine your .pem/.crt CA files"
say "Select the issuing root CA and any required intermediate CA certificates."
say "PEM bundles and DER .crt files are accepted; duplicates are included once."
say "Enter one path at a time, without surrounding quotes. In WSL use /mnt/c/..."
touch "$work_dir/ca-bundle.pem"
while true; do
  ask CA_CERTIFICATE "Path to a CA certificate file:"
  if [[ "$CA_CERTIFICATE" == "~/"* ]]; then CA_CERTIFICATE="$HOME/${CA_CERTIFICATE:2}"; fi
  if [[ -z "$CA_CERTIFICATE" || ! -f "$CA_CERTIFICATE" ]]; then
    warn "File not found. Enter a readable path."
    continue
  fi
  if ! ca_helper cert "$CA_CERTIFICATE" "$work_dir/ca-bundle.pem"; then
    warn "Nothing from this file was added. Choose another CA file."
    continue
  fi
  write_env CA_CERTIFICATE "$CA_CERTIFICATE"
  confirm "Add another CA certificate file?" || break
done
[[ -s "$work_dir/ca-bundle.pem" ]] || die "No CA certificates were selected."
pause "Certificates validated. Press Enter to continue."

stage "Prepare and review the persistent Helm configuration"
say "Use the repository URL from Newsletter's import settings, without credentials."
while true; do
  ask CA_REPOSITORY_URL "HTTPS Artifactory repository URL:"
  if CA_CHECK_URL=$(ca_helper url "$CA_REPOSITORY_URL"); then break; fi
done
write_env CA_REPOSITORY_URL "$CA_REPOSITORY_URL"
output_dir=$(mktemp -d "$PWD/newsletter-ca-setup.XXXXXX")
cp "$CA_VALUES" "$output_dir/original-values.yaml"
ca_helper values "$CA_VALUES" "$work_dir/ca-bundle.pem" "$output_dir/updated-values.yaml"
render_args=()
if [[ "$CA_MANAGER" == helm ]]; then
  # Reuse explicitly supplied release values, while retaining new chart defaults.
  render_args+=(-f "$work_dir/release-values.yaml")
fi
render_args+=("${additional_values[@]}" -f "$output_dir/updated-values.yaml")
if ! helm template "$CA_RELEASE" "$chart_dir" "--namespace=$CA_NAMESPACE" \
  "${render_args[@]}" > "$output_dir/rendered-plan.yaml" 2> "$output_dir/helm-render.log"; then
  die "Chart rendering failed. Inspect $output_dir/helm-render.log privately. The values file was not changed."
fi
k get deployment "$CA_DEPLOYMENT" -o json > "$work_dir/live.json"
ca_helper verify-plan "$work_dir/live.json" "$output_dir/rendered-plan.yaml"
say "Cluster: $CA_CONTEXT"
say "Namespace / Deployment: $CA_NAMESPACE / $CA_DEPLOYMENT"
say "Release / manager: $CA_RELEASE / $CA_MANAGER"
say "Values file to update: $CA_VALUES"
say "Private backup and review files: $output_dir"
warn "The review files include existing values; keep them private."
if [[ "$CA_MANAGER" == helm ]]; then
  say "Helm will reconcile the release with this chart and values, restarting Newsletter."
else
  say "The wizard updates the local values file. Your GitOps process will deploy it."
fi
if ! confirm "Save this persistent CA configuration and proceed?"; then
  say "No values or cluster resources were changed. Review files remain in $output_dir."
  exit 0
fi
cp "$output_dir/updated-values.yaml" "$CA_VALUES"
say "Saved public CA bundle under artifactoryCa.bundle in $CA_VALUES."

stage "Deploy through Helm or your GitOps workflow"
if [[ "$CA_MANAGER" == helm ]]; then
  # Match the reviewed render: current release values plus selected overrides.
  if ! h upgrade "$CA_RELEASE" "$chart_dir" --reset-values \
    "${render_args[@]}" --wait --timeout 180s > "$output_dir/helm-upgrade.log" 2>&1; then
    warn "Helm upgrade failed or timed out. The CA remains saved in the values file."
    say "Inspect: helm --kube-context \"$CA_CONTEXT\" -n \"$CA_NAMESPACE\" status \"$CA_RELEASE\""
    say "Local values backup: $output_dir/original-values.yaml"
    say "Private Helm output: $output_dir/helm-upgrade.log"
    say "Use helm history/rollback for the release if needed; the wizard does not roll it back automatically."
    exit 1
  fi
else
  say "Commit/publish the CA values file and the updated Helm chart through your normal GitOps process."
  say "Chart changes: templates/artifactory-ca.yaml, templates/deployment.yaml,"
  say "templates/_helpers.tpl and values.yaml."
  say "The Application must use that chart revision and the selected values file."
  say "Sync the Application in ArgoCD, then wait for the new pod to be healthy."
  if ! confirm "Have you deployed/synced those files to the selected cluster?"; then
    say "Persistent configuration is prepared. Finish the GitOps sync and re-run to verify."
    exit 0
  fi
fi
if ! k rollout status "deployment/$CA_DEPLOYMENT" --timeout=180s; then
  die "The Deployment did not become ready. Inspect the pod events and release status."
fi

stage "Verify TLS and retain the CA for future upgrades"
k get deployment "$CA_DEPLOYMENT" -o json > "$work_dir/live.json"
ca_helper verify-installed "$work_dir/live.json" "$work_dir/ca-bundle.pem"
say "Testing the Artifactory repository API from Newsletter without credentials..."
probe_js='
const url = process.argv[1];
fetch(url, {redirect: "manual", signal: AbortSignal.timeout(15000)})
  .then(response => {
    console.log("TLS verification succeeded. HTTP " + response.status);
    if (response.status >= 300 && response.status < 400)
      console.log("This endpoint redirects; use a direct Artifactory repository URL.");
    else if (response.status === 401 || response.status === 403)
      console.log("Authorization is required; this check sent no credentials.");
    else if (!response.ok)
      console.log("Check the repository URL and server response before retrying the import.");
  })
  .catch(error => {
    const pending = [error], seen = new Set();
    console.error("Connection/TLS verification failed:");
    while (pending.length && seen.size < 32) {
      const current = pending.shift();
      if (!current || typeof current !== "object" || seen.has(current)) continue;
      seen.add(current);
      if (current.code || current.name === "TimeoutError") console.error(current.code || current.name);
      pending.push(current.cause);
      if (Array.isArray(current.errors)) pending.push(...current.errors.slice(0, 32));
    }
    process.exitCode = 1;
  });'
if ! k exec "deployment/$CA_DEPLOYMENT" -c newsletter -- node -e "$probe_js" "$CA_CHECK_URL"; then
  warn "Configuration is persistent, but TLS is still failing."
  say "Check the issuing CA bundle and Artifactory's served intermediate certificates."
  say "Backup/review files: $output_dir"
  exit 1
fi
say "Keep artifactoryCa.bundle in $CA_VALUES when you change the image version."
say "Retain the new CA templates in your chart. CA changes restart the pod automatically."
say "Future deployments must continue using this values file."
say "Local values backup: $output_dir/original-values.yaml"
say "Retry the Newsletter import to verify repository credentials and document access."
pause "Press Enter to finish."
finish
